var trayIcon []byte

//go:build darwin

package main

import _ "embed"

//go:embed build/trayicon.png
var trayIcon []byte

package tray

import (
	"sync"

	"github.com/wailsapp/wails/v3/pkg/application"
)

// Controller manages the system tray icon and menu via Wails v3.
type Controller struct {
	app  *application.App
	icon []byte
	cb   Callbacks
	opts Options

	mu            sync.Mutex
	tray          *application.SystemTray
	menu          *application.Menu
	statusItem    *application.MenuItem
	autostartItem *application.MenuItem
	langItems     map[string]*application.MenuItem
	started       bool
}

// New creates a tray controller. icon should be PNG bytes on all platforms.
func New(app *application.App, icon []byte, cb Callbacks, opts Options) *Controller {
	return &Controller{
		app:       app,
		icon:      icon,
		cb:        cb,
		opts:      opts,
		langItems: map[string]*application.MenuItem{},
	}
}

// Start creates the system tray and attaches the menu.
func (c *Controller) Start() {
	c.mu.Lock()
	if c.started || c.app == nil {
		c.mu.Unlock()
		return
	}
	c.started = true
	c.mu.Unlock()

	systray := c.app.SystemTray.New()
	if len(c.icon) > 0 {
		systray.SetIcon(c.icon)
		systray.SetTemplateIcon(c.icon)
	}
	tooltip := or(c.opts.Labels.Tooltip, "Gotify Desktop")
	systray.SetTooltip(tooltip)
	systray.SetLabel("")
	systray.OnClick(func() {
		if c.cb.OnOpen != nil {
			c.cb.OnOpen()
		}
	})

	menu := c.buildMenu()
	systray.SetMenu(menu)

	c.mu.Lock()
	c.tray = systray
	c.menu = menu
	c.mu.Unlock()
}

// Stop destroys the system tray.
func (c *Controller) Stop() {
	c.mu.Lock()
	t := c.tray
	c.tray = nil
	c.started = false
	c.mu.Unlock()
	if t != nil {
		t.Destroy()
	}
}

// SetStatus updates the status menu label.
func (c *Controller) SetStatus(text string) {
	c.mu.Lock()
	item := c.statusItem
	menu := c.menu
	c.mu.Unlock()
	if item == nil {
		return
	}
	item.SetLabel(text)
	if menu != nil {
		menu.Update()
	}
}

// SetAutostartChecked updates the Start at login checkbox.
func (c *Controller) SetAutostartChecked(enabled bool) {
	c.mu.Lock()
	item := c.autostartItem
	menu := c.menu
	c.opts.AutostartEnabled = enabled
	c.mu.Unlock()
	if item == nil {
		return
	}
	item.SetChecked(enabled)
	if menu != nil {
		menu.Update()
	}
}

// SetLabels refreshes tray menu titles after a locale change by rebuilding the menu.
func (c *Controller) SetLabels(l Labels) {
	c.mu.Lock()
	c.opts.Labels = l
	tray := c.tray
	c.mu.Unlock()
	if tray == nil {
		return
	}
	if l.Tooltip != "" {
		tray.SetTooltip(l.Tooltip)
	}
	menu := c.buildMenu()
	tray.SetMenu(menu)
	c.mu.Lock()
	c.menu = menu
	c.mu.Unlock()
}

// SetLocaleChecked marks the active language in the submenu.
func (c *Controller) SetLocaleChecked(code string) {
	c.mu.Lock()
	items := c.langItems
	menu := c.menu
	c.opts.Locale = code
	c.mu.Unlock()
	for id, item := range items {
		if item == nil {
			continue
		}
		item.SetChecked(id == code)
	}
	if menu != nil {
		menu.Update()
	}
}

func (c *Controller) buildMenu() *application.Menu {
	l := c.opts.Labels
	menu := c.app.NewMenu()

	status := menu.Add(or(l.StatusStarting, "Status: starting…"))
	status.SetEnabled(false)

	menu.AddSeparator()
	menu.Add(or(l.Open, "Open window")).OnClick(func(_ *application.Context) {
		if c.cb.OnOpen != nil {
			c.cb.OnOpen()
		}
	})
	menu.Add(or(l.Settings, "Settings")).OnClick(func(_ *application.Context) {
		if c.cb.OnSettings != nil {
			c.cb.OnSettings()
		}
	})
	menu.Add(or(l.History, "Recent notifications")).OnClick(func(_ *application.Context) {
		if c.cb.OnHistory != nil {
			c.cb.OnHistory()
		}
	})
	menu.Add(or(l.Send, "Send message")).OnClick(func(_ *application.Context) {
		if c.cb.OnSend != nil {
			c.cb.OnSend()
		}
	})

	autostart := menu.AddCheckbox(or(l.Autostart, "Start at login"), c.opts.AutostartEnabled)
	autostart.OnClick(func(ctx *application.Context) {
		enabled := false
		if item := ctx.ClickedMenuItem(); item != nil {
			enabled = item.Checked()
		}
		if c.cb.OnAutostart != nil {
			c.cb.OnAutostart(enabled)
		}
	})

	langMenu := menu.AddSubmenu(or(l.Language, "Language"))
	langItems := map[string]*application.MenuItem{}
	for _, lang := range c.opts.Languages {
		code := lang.Code
		item := langMenu.AddRadio(lang.Name, code == c.opts.Locale)
		item.OnClick(func(_ *application.Context) {
			if c.cb.OnLanguage != nil {
				c.cb.OnLanguage(code)
			}
		})
		langItems[code] = item
	}

	about := menu.AddSubmenu(or(l.About, "About"))
	aboutAuthor := about.Add(or(l.AboutAuthor, "Author"))
	aboutAuthor.SetEnabled(false)
	about.Add(or(l.AboutLicense, "License")).OnClick(func(_ *application.Context) {
		if c.cb.OnAboutLicense != nil {
			c.cb.OnAboutLicense()
		}
	})
	about.Add(or(l.AboutVersion, "Version")).OnClick(func(_ *application.Context) {
		if c.cb.OnAboutVersion != nil {
			c.cb.OnAboutVersion()
		}
	})
	about.Add(or(l.AboutCheckUpdates, "Check for updates")).OnClick(func(_ *application.Context) {
		if c.cb.OnAboutCheckUpdates != nil {
			c.cb.OnAboutCheckUpdates()
		}
	})
	about.Add(or(l.AboutRepo, "Open repository")).OnClick(func(_ *application.Context) {
		if c.cb.OnAboutRepo != nil {
			c.cb.OnAboutRepo()
		}
	})

	menu.AddSeparator()
	menu.Add(or(l.Quit, "Quit")).OnClick(func(_ *application.Context) {
		if c.cb.OnQuit != nil {
			c.cb.OnQuit()
		}
	})

	c.mu.Lock()
	c.statusItem = status
	c.autostartItem = autostart
	c.langItems = langItems
	c.mu.Unlock()

	return menu
}

func or(v, fallback string) string {
	if v != "" {
		return v
	}
	return fallback
}

package notify

import (
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
	"runtime"
	"sync"

	"github.com/elpatron68/gotify-desktop/internal/applog"
	"github.com/wailsapp/wails/v3/pkg/services/notifications"
)

// Notifier wraps Wails native notifications with a platform fallback.
type Notifier struct {
	mu      sync.Mutex
	svc     *notifications.NotificationService
	ready   bool
	initErr error
	lastErr error
	logger  *log.Logger
	logFile io.Closer
}

// Init initializes the platform notification system.
// On Windows the Wails notifier is skipped in favour of native AUMID toasts.
func (n *Notifier) Init(svc *notifications.NotificationService) error {
	n.mu.Lock()
	defer n.mu.Unlock()
	n.svc = svc
	n.ensureLogger()

	// Windows: never use Wails/WebView2 notifications — they appear as
	// "wails.localhost". Native AUMID toasts show "Gotify Desktop" instead.
	if runtime.GOOS == "windows" {
		n.ready = false
		n.initErr = nil
		n.logf("using native Windows toasts (skipping Wails notifier)")
		applog.Printf("notify init ready GOOS=windows backend=native-aumid")
		return nil
	}

	if svc == nil {
		n.initErr = fmt.Errorf("notifications service unavailable")
		n.ready = false
		n.logf("%v (will use platform fallback)", n.initErr)
		return n.initErr
	}

	authorized, err := svc.CheckNotificationAuthorization()
	if err == nil && !authorized {
		authorized, err = svc.RequestNotificationAuthorization()
		if err != nil || !authorized {
			n.initErr = fmt.Errorf("notification permission denied")
			n.ready = false
			n.logf("%v (will use platform fallback)", n.initErr)
			return n.initErr
		}
	}
	n.ready = true
	n.initErr = nil
	n.logf("wails notifications ready (GOOS=%s)", runtime.GOOS)
	applog.Printf("notify init ready GOOS=%s", runtime.GOOS)
	return nil
}

// Ready reports whether the Wails notification backend initialized.
func (n *Notifier) Ready() bool {
	n.mu.Lock()
	defer n.mu.Unlock()
	return n.ready
}

// LastError returns the last notification send/init error, if any.
func (n *Notifier) LastError() string {
	n.mu.Lock()
	defer n.mu.Unlock()
	if n.lastErr != nil {
		return n.lastErr.Error()
	}
	if n.initErr != nil && !n.ready {
		return n.initErr.Error()
	}
	return ""
}

// Show displays a desktop notification.
//
// On Windows, Wails/WinRT often reports success for unpackaged apps without a
// visible toast (missing Start Menu AUMID shortcut). We therefore always use the
// PowerShell AUMID fallback on Windows. On other OSes, try Wails first, then beeep.
func (n *Notifier) Show(id, title, body string) error {
	n.mu.Lock()
	svc := n.svc
	ready := n.ready
	n.ensureLogger()
	n.mu.Unlock()

	if title == "" {
		title = "Gotify" // brand fallback; UI should pass a localized title when empty matters
	}

	if runtime.GOOS == "windows" {
		if err := showPlatformToast(title, body); err != nil {
			n.setLastErr(err)
			n.logf("windows toast failed id=%s: %v", id, err)
			return err
		}
		n.setLastErr(nil)
		n.logf("windows toast sent id=%s title=%q (also see desktop.log for method/Setting)", id, title)
		applog.Printf("notify Show ok id=%s title=%q", id, title)
		return nil
	}

	var firstErr error
	if ready && svc != nil {
		err := svc.SendNotification(notifications.NotificationOptions{
			ID:    id,
			Title: title,
			Body:  body,
		})
		if err == nil {
			n.setLastErr(nil)
			n.logf("wails notification sent id=%s title=%q", id, title)
			return nil
		}
		firstErr = err
		n.logf("wails SendNotification failed: %v — trying fallback", err)
	}

	if err := showPlatformToast(title, body); err != nil {
		if firstErr != nil {
			err = fmt.Errorf("wails: %v; fallback: %w", firstErr, err)
		}
		n.setLastErr(err)
		n.logf("notification failed: %v", err)
		return err
	}
	n.setLastErr(nil)
	n.logf("fallback notification sent title=%q", title)
	return nil
}

func (n *Notifier) setLastErr(err error) {
	n.mu.Lock()
	n.lastErr = err
	n.mu.Unlock()
}

// Close releases the notify.log file handle. Safe to call multiple times.
func (n *Notifier) Close() {
	n.mu.Lock()
	defer n.mu.Unlock()
	if n.logFile != nil {
		_ = n.logFile.Close()
		n.logFile = nil
	}
	// Keep a stderr logger so late logf calls after Close stay safe.
	n.logger = log.New(os.Stderr, "gotify-desktop/notify: ", log.LstdFlags|log.Lmsgprefix)
}

// ensureLogger initializes the file logger. Caller must hold n.mu.
func (n *Notifier) ensureLogger() {
	if n.logger != nil {
		return
	}
	n.logger = log.New(os.Stderr, "gotify-desktop/notify: ", log.LstdFlags|log.Lmsgprefix)
	dir, err := os.UserConfigDir()
	if err != nil {
		return
	}
	logDir := filepath.Join(dir, "gotify-desktop")
	if err := os.MkdirAll(logDir, 0o700); err != nil {
		return
	}
	f, err := os.OpenFile(filepath.Join(logDir, "notify.log"), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return
	}
	n.logFile = f
	n.logger = log.New(f, "", log.LstdFlags)
}

func (n *Notifier) logf(format string, args ...any) {
	// logger is set under mu and only swapped in Close; reading the pointer
	// without the lock is safe. Avoid locking here: Init calls logf while
	// already holding n.mu.
	if n.logger != nil {
		n.logger.Printf(format, args...)
	}
}

package main

import (
	"context"
	"fmt"
	"os"
	"time"

	"github.com/elpatron68/gotify-desktop/internal/applog"
	"github.com/elpatron68/gotify-desktop/internal/config"
	"github.com/elpatron68/gotify-desktop/internal/i18n"
	"github.com/elpatron68/gotify-desktop/internal/update"
	"github.com/elpatron68/gotify-desktop/internal/version"
)

const updateCheckInterval = 24 * time.Hour

// CheckForUpdates runs a manual update check (menu / tray).
func (a *App) CheckForUpdates() {
	go a.runUpdateCheck(true)
}

func (a *App) maybeAutoCheckUpdates() {
	go func() {
		// Let DomReady and the window settle before showing a dialog.
		time.Sleep(3 * time.Second)
		a.runUpdateCheck(false)
	}()
}

func (a *App) runUpdateCheck(manual bool) {
	if version.Version == "0.0.0" {
		if manual {
			a.showUpdateInfo(i18n.T("update.dev_build"))
		}
		return
	}

	if !manual {
		a.mu.Lock()
		last := a.cfg.UpdateCheckedUnix
		a.mu.Unlock()
		if last > 0 && time.Since(time.Unix(last, 0)) < updateCheckInterval {
			return
		}
	}

	client := &update.Client{UserAgent: "gotify-desktop/" + version.Version}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	rel, err := client.LatestRelease(ctx)
	if err != nil {
		applog.Printf("update check failed: %v", err)
		if manual {
			a.showUpdateError(i18n.Tf("update.check_failed", map[string]string{"Error": err.Error()}))
		}
		return
	}
	a.markUpdateChecked()

	current := version.Version
	latest := update.NormalizeTag(rel.TagName)
	newer, err := update.IsNewer(latest, current)
	if err != nil {
		applog.Printf("update version compare: %v", err)
		if manual {
			a.showUpdateError(i18n.Tf("update.check_failed", map[string]string{"Error": err.Error()}))
		}
		return
	}
	if !newer {
		if manual {
			a.showUpdateInfo(i18n.Tf("update.up_to_date", map[string]string{"Version": current}))
		}
		return
	}

	target, err := update.DetectTarget("", "")
	if err != nil {
		applog.Printf("update detect target: %v", err)
		if manual {
			a.showUpdateError(i18n.Tf("update.check_failed", map[string]string{"Error": err.Error()}))
		}
		return
	}
	asset := update.SelectAsset(rel.Assets, target)
	if asset == nil {
		msg := i18n.Tf("update.no_asset", map[string]string{"Version": latest})
		if manual {
			a.showUpdateInfo(msg)
		} else {
			applog.Printf("update: %s", msg)
		}
		return
	}

	msg := i18n.Tf("update.available", map[string]string{
		"Current": current,
		"Latest":  latest,
	})
	if !a.askUpdateQuestion(msg) {
		return
	}

	if target.Kind == update.InstallBinary || target.Kind == update.InstallAppImage || target.Kind == update.InstallWindowsEXE {
		if !update.CanWriteBeside(target.ReplacePath) && target.Kind != update.InstallWindowsEXE {
			a.showUpdateError(i18n.T("update.need_write"))
			return
		}
	}

	downloadCtx, downloadCancel := context.WithTimeout(context.Background(), 10*time.Minute)
	defer downloadCancel()
	path, err := client.Download(downloadCtx, asset.BrowserDownloadURL, asset.Name)
	if err != nil {
		a.showUpdateError(i18n.Tf("update.download_failed", map[string]string{"Error": err.Error()}))
		return
	}
	defer os.Remove(path)

	sumURL := update.ChecksumURL(asset.BrowserDownloadURL)
	if sumURL != "" {
		if err := client.VerifyChecksum(downloadCtx, path, sumURL, asset.Name); err != nil {
			applog.Printf("update checksum: %v", err)
			a.showUpdateError(i18n.Tf("update.checksum_failed", map[string]string{"Error": err.Error()}))
			return
		}
	}

	exe, err := os.Executable()
	if err != nil {
		a.showUpdateError(err.Error())
		return
	}
	if err := update.LaunchApply(exe, path, target); err != nil {
		a.showUpdateError(i18n.Tf("update.apply_failed", map[string]string{"Error": err.Error()}))
		return
	}
	a.Quit()
}

func (a *App) markUpdateChecked() {
	now := time.Now().Unix()
	a.mu.Lock()
	a.cfg.UpdateCheckedUnix = now
	cfg := a.cfg
	a.mu.Unlock()
	if err := config.Save(cfg); err != nil {
		applog.Printf("save update_checked_unix: %v", err)
	}
}

func (a *App) askUpdateQuestion(message string) bool {
	if a.wailsApp == nil {
		return false
	}
	done := make(chan bool, 1)
	dialog := a.wailsApp.Dialog.Question().
		SetTitle(i18n.T("update.title")).
		SetMessage(message)
	install := dialog.AddButton(i18n.T("update.install"))
	later := dialog.AddButton(i18n.T("update.later"))
	dialog.SetDefaultButton(install)
	dialog.SetCancelButton(later)
	install.OnClick(func() { done <- true })
	later.OnClick(func() { done <- false })
	dialog.Show()
	return <-done
}

func (a *App) showUpdateInfo(message string) {
	if a.wailsApp == nil {
		return
	}
	a.wailsApp.Dialog.Info().
		SetTitle(i18n.T("update.title")).
		SetMessage(message).
		Show()
}

func (a *App) showUpdateError(message string) {
	if a.wailsApp == nil {
		return
	}
	a.wailsApp.Dialog.Error().
		SetTitle(i18n.T("update.title")).
		SetMessage(message).
		Show()
}

