func applyTrayTitle(systray *application.SystemTray, tooltip string) {
	if systray == nil {
		return
	}
	title := or(tooltip, "Gotify Desktop")
	systray.SetTooltip(title)
	if runtime.GOOS == "linux" {
		systray.SetLabel(title)
		return
	}
	systray.SetLabel("")
